const websocketSessionCache = new Map();

export function write(key, value) {
  websocketSessionCache.set(key, value);
}

export function read(key) {
  return websocketSessionCache.get(key);
}

export function readThrough(map, key) {
  return map.get(key);
}

export function readOwnThrough(key) {
  return readThrough(websocketSessionCache, key);
}

export function schedule(key) {
  return () => websocketSessionCache.get(key);
}

export function remove(key) {
  return websocketSessionCache.delete(key);
}

export function reset() {
  websocketSessionCache.clear();
}

export function iteratorLengths() {
  const keys = Array.from(websocketSessionCache.keys());
  const values = Array.from(websocketSessionCache.values());
  const entries = Array.from(websocketSessionCache.entries());
  let entryCount = 0;
  for (const _entry of entries) entryCount++;
  return `${keys.length},${values.length},${entryCount}`;
}

export function keysText() {
  return Array.from(websocketSessionCache.keys()).join(",");
}

export function valuesText() {
  return [...websocketSessionCache.values()].join(",");
}

export function entriesText() {
  let out = "";
  for (const [key, value] of websocketSessionCache.entries()) out += `${key}:${value}|`;
  return out;
}

export function valuesLoop() {
  let out = "";
  for (const value of websocketSessionCache.values()) out += `${value},`;
  return out;
}
